const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const message = String(body.message || body.text || body.request || '').trim();
const chatId = body.chat_id || 'local-project-chat';
const state = body.conversation_state || {};
const availableTime = String(body.available_time || body.availableTime || state.available_time || 'unknown');
const preferredMode = String(body.preferred_mode || body.preferredMode || state.preferred_mode || 'any');
const maxOptions = Math.min(Number(body.max_options || body.maxOptions || 3), 3);
const dryRun = body.dry_run === true;

const prompt = [
  'Actua como gateway conversacional del proyecto Invernadero Central usando AGENT-PMO-001.',
  'Tu alcance esta estrictamente limitado al proyecto: sensores, edge, datos, web, n8n, agentes, backlog, Kanban, roadmap, evidencia, arquitectura, mercado/growth documentado y decisiones versionadas.',
  'Si el humano pregunta algo fuera del proyecto, responde brevemente que solo puedes ayudar con el proyecto y ofrece una forma de reformularlo dentro del contexto del proyecto.',
  `Mensaje humano: ${message || '(vacio)'}.`,
  `chat_id: ${chatId}.`,
  `conversation_state: ${JSON.stringify(state)}.`,
  `Tiempo disponible humano: ${availableTime}.`,
  `Modo preferido: ${preferredMode}.`,
  `Maximo de opciones: ${maxOptions}.`,
  'Usa el contexto versionado del repo central y el baseline actual. Debes poder responder preguntas sobre estado del proyecto, backlog, roadmap, agentes, HUs, riesgos y siguiente mejor accion.',
  'Clasifica la intencion y decide el agente recomendado: project-pmo, project-planning, project-backlog, project-refinement, project-architecture, project-engineering, project-qa-evidence o project-reviewer-safety.',
  'Si se pide planificar desde estado actual, recomienda project-planning. Si se pide siguiente accion, backlog, prioridad, WIP o desbloqueo, responde como PMO. Si se pide refinar HU/enabler/spike/experiment/task, recomienda project-refinement. Si se pide codigo o implementacion, verifica si hay HU refinada y aprobacion; si no, pide el paso faltante. Si se pide DONE/evidencia, recomienda project-qa-evidence.',
  'No muevas estados Kanban, no marques DONE, no edites HU congeladas, no apruebes compras, no ejecutes despliegues criticos ni controles fisicos.',
  'Responde en espanol, sin emojis, con maximo 3 opciones cuando recomiendes trabajo, y haz una sola pregunta final si necesitas decision humana.',
  'Devuelve una respuesta util para mostrar directamente en el chat. Incluye route con recommended_agent y next_question si aplica.'
].join(' ');

return [{
  json: {
    agent: 'project-pmo',
    workspace: 'central',
    prompt,
    mode: 'chat-gateway',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'CHAT-GATEWAY-001',
      gateway_agent: 'AGENT-PMO-001',
      chat_id: chatId,
      available_time: availableTime,
      preferred_mode: preferredMode,
      max_options: maxOptions,
      scope: 'project_only'
    }
  }
}];

const runner = items && items[0] && items[0].json ? items[0].json : {};
const stripAnsi = (value) => String(value || '').replace(/\u001b\[[0-9;?]*[ -/]*[@-~]/g, '').trim();
const stripToolLogs = (value) => {
  let text = stripAnsi(value);
  const markers = ['## AGENT-PMO-001', '## AGENT-PMO', '## Diagnostico', '## Diagnóstico', '### Estado actual', 'route:'];
  const positions = markers.map((marker) => text.indexOf(marker)).filter((index) => index >= 0);
  if (positions.length > 0) {
    text = text.slice(Math.min(...positions)).trim();
  }
  return text
    .split('\n')
    .filter((line) => !/^Batch fs_read operation/.test(line))
    .filter((line) => !/^↱ Operation/.test(line))
    .filter((line) => !/^ ✓ Successfully read/.test(line))
    .filter((line) => !/^ ⋮ /.test(line))
    .filter((line) => !/^- Summary:/.test(line))
    .filter((line) => !/^ - Completed/.test(line))
    .filter((line) => !/^Reading file:/.test(line))
    .filter((line) => !/^> /.test(line))
    .join('\n')
    .trim();
};
const stdout = stripToolLogs(runner.stdout);
const stderr = stripAnsi(runner.stderr);
const reply = stdout || (runner.dry_run ? 'Gateway PMO validado en dry_run. El chat esta conectado al agente project-pmo.' : 'No recibi salida del agente PMO.');

return [{
  json: {
    status: runner.status || 'UNKNOWN',
    chat_scope: 'project_only',
    reply,
    route: {
      workflow: 'CHAT-GATEWAY-001',
      gateway_agent: 'AGENT-PMO-001',
      primary_agent: runner.agent || 'project-pmo',
      authority: 'A1',
      review_required: runner.requires_human_review !== false
    },
    constraints: [
      'Solo responder o trabajar con contexto del proyecto Invernadero Central.',
      'No modificar HU congeladas.',
      'No mover estados sin aprobacion humana.',
      'No marcar DONE sin evidencia.',
      'No aprobar compras, despliegues criticos ni control fisico.',
      'Hacer una sola pregunta al humano por turno.'
    ],
    runner: {
      dry_run: !!runner.dry_run,
      exit_code: runner.exit_code,
      duration_ms: runner.duration_ms,
      auth_source: runner.auth && runner.auth.source,
      error: runner.error || null,
      stderr
    }
  }
}];
